/**
 * Wave 7 / Builder 7 — bot LLM intercept tests.
 *
 * Replaces the disposable Spike C termination test
 * (`spike-c-termination.test.ts`). Now targets the production helper
 * `interceptCreateForModal()` and the `stopOnModalOpened` predicate that ships
 * to bot.ts.
 *
 * Coverage:
 *   - single intercept proposal insertion + flag set
 *   - multi-detect parallel calls (same step) all allowed; share intent_group_id
 *   - subsequent-step rejection when modal already open
 *   - stopOnModalOpened predicate behavior on tool result shape
 *   - extractInterceptedProposals over result.steps
 *   - composeButtonBearingReply: single, multi, mixed read+create
 *   - retainer-cue propagation (isRetainer === true -> kind === "retainer")
 *   - feature-flag short-circuit when disabled
 */

import { describe, it, expect, vi, beforeEach } from "vitest";

// --------------------------------------------------------------------------
// Hoisted mocks — proposal.insertProposal + feature-flags
// --------------------------------------------------------------------------

const { mockInsertProposal, mockFlagState } = vi.hoisted(() => {
  const mockInsertProposal = vi.fn();
  const mockFlagState = { enabled: true };
  return { mockInsertProposal, mockFlagState };
});

vi.mock("./modals/proposal", () => ({
  insertProposal: mockInsertProposal,
}));

vi.mock("@/lib/feature-flags", () => ({
  isModalInterceptEnabled: () => mockFlagState.enabled,
}));

// Re-import after mocks register.
import {
  interceptCreateForModal,
  stopOnModalOpened,
  extractInterceptedProposals,
  composeButtonBearingReply,
  type ConvoState,
  type InterceptResult,
} from "./intercept";

function freshConvo(): ConvoState {
  return { modalAlreadyOpened: false, openStep: null, currentStep: 0 };
}

const baseContext = {
  slackUserId: "U_USER",
  channelId: "D_CHAN",
  threadTs: null,
  intentGroupId: "ig_test_1",
};

beforeEach(() => {
  mockInsertProposal.mockReset();
  mockFlagState.enabled = true;
  // Default: every insert returns a unique-ish id derived from call count.
  mockInsertProposal.mockImplementation(async () => ({
    proposalId: `prop_${mockInsertProposal.mock.calls.length}`,
  }));
});

describe("interceptCreateForModal — single create", () => {
  it("inserts proposal, sets flag + openStep, returns modalOpened payload", async () => {
    const convoState = freshConvo();
    convoState.currentStep = 0;

    const result = await interceptCreateForModal({
      toolName: "create_week_item",
      args: { title: "Concept Writeup", date: "2026-05-04" },
      context: baseContext,
      convoState,
    });

    expect("modalOpened" in result && result.modalOpened).toBe(true);
    if ("modalOpened" in result) {
      expect(result.proposalId).toBe("prop_1");
      expect(result.kind).toBe("task");
      expect(result.title).toBe("Concept Writeup");
    }

    expect(convoState.modalAlreadyOpened).toBe(true);
    expect(convoState.openStep).toBe(0);

    expect(mockInsertProposal).toHaveBeenCalledOnce();
    const insertArgs = mockInsertProposal.mock.calls[0][0];
    expect(insertArgs.kind).toBe("create");
    expect(insertArgs.toolName).toBe("create_week_item");
    expect(insertArgs.userSlackId).toBe("U_USER");
    expect(insertArgs.intentGroupId).toBe("ig_test_1");
  });

  it("maps create_project (isRetainer=false) -> kind 'project'", async () => {
    const convoState = freshConvo();
    const result = await interceptCreateForModal({
      toolName: "create_project",
      args: { name: "AG1 Pro Q1", clientSlug: "ag1" },
      context: baseContext,
      convoState,
    });
    expect("modalOpened" in result && result.kind).toBe("project");
    expect("modalOpened" in result && result.title).toBe("AG1 Pro Q1");
  });

  it("maps create_project with isRetainer=true -> kind 'retainer'", async () => {
    const convoState = freshConvo();
    const result = await interceptCreateForModal({
      toolName: "create_project",
      args: { name: "AG1 Pro 2026", clientSlug: "ag1", isRetainer: true },
      context: baseContext,
      convoState,
    });
    expect("modalOpened" in result && result.kind).toBe("retainer");
  });

  it("maps create_team_member -> kind 'team_member' and reads fullName for title", async () => {
    const convoState = freshConvo();
    const result = await interceptCreateForModal({
      toolName: "create_team_member",
      args: { name: "Lane", fullName: "Lane Davis" },
      context: baseContext,
      convoState,
    });
    expect("modalOpened" in result && result.kind).toBe("team_member");
    expect("modalOpened" in result && result.title).toBe("Lane Davis");
  });

  it("falls back to args.name when fullName is missing on create_team_member", async () => {
    const convoState = freshConvo();
    const result = await interceptCreateForModal({
      toolName: "create_team_member",
      args: { name: "Lane" },
      context: baseContext,
      convoState,
    });
    expect("modalOpened" in result && result.title).toBe("Lane");
  });

  it("propagates pendingProjectName from args to insertProposal + result", async () => {
    const convoState = freshConvo();
    const result = await interceptCreateForModal({
      toolName: "create_week_item",
      args: { title: "Concept Writeup", pendingProjectName: "AG1 Pro 2026" },
      context: baseContext,
      convoState,
    });
    expect("modalOpened" in result && result.parentProjectName).toBe("AG1 Pro 2026");
    const insertArgs = mockInsertProposal.mock.calls[0][0];
    expect(insertArgs.pendingProjectName).toBe("AG1 Pro 2026");
  });
});

describe("interceptCreateForModal — step-aware flag", () => {
  it("allows N parallel calls in the SAME step (multi-detect)", async () => {
    const convoState = freshConvo();
    convoState.currentStep = 0;

    const r1 = await interceptCreateForModal({
      toolName: "create_project",
      args: { name: "AG1 Pro 2026", isRetainer: true },
      context: baseContext,
      convoState,
    });
    const r2 = await interceptCreateForModal({
      toolName: "create_week_item",
      args: { title: "Concept Writeup", date: "2026-05-04", pendingProjectName: "AG1 Pro 2026" },
      context: baseContext,
      convoState,
    });
    const r3 = await interceptCreateForModal({
      toolName: "create_week_item",
      args: { title: "Concept Writeup", date: "2026-05-11", pendingProjectName: "AG1 Pro 2026" },
      context: baseContext,
      convoState,
    });

    expect("modalOpened" in r1 && r1.modalOpened).toBe(true);
    expect("modalOpened" in r2 && r2.modalOpened).toBe(true);
    expect("modalOpened" in r3 && r3.modalOpened).toBe(true);
    expect(mockInsertProposal).toHaveBeenCalledTimes(3);
    // All three share the same intent_group_id (came from context).
    for (const call of mockInsertProposal.mock.calls) {
      expect(call[0].intentGroupId).toBe("ig_test_1");
    }
  });

  it("rejects when called in a SUBSEQUENT step after modal opened in step 0", async () => {
    const convoState = freshConvo();
    convoState.currentStep = 0;

    const r1 = await interceptCreateForModal({
      toolName: "create_week_item",
      args: { title: "First task" },
      context: baseContext,
      convoState,
    });
    expect("modalOpened" in r1 && r1.modalOpened).toBe(true);

    // LLM kept looping somehow. We're now in step 1.
    convoState.currentStep = 1;
    const r2 = await interceptCreateForModal({
      toolName: "create_week_item",
      args: { title: "Second task" },
      context: baseContext,
      convoState,
    });
    expect("error" in r2).toBe(true);
    expect("error" in r2 && r2.error).toMatch(/already open/i);
    // 2nd call did NOT insert another proposal.
    expect(mockInsertProposal).toHaveBeenCalledOnce();
  });
});

describe("interceptCreateForModal — feature flag", () => {
  it("returns error when isModalInterceptEnabled() is false", async () => {
    mockFlagState.enabled = false;
    const convoState = freshConvo();
    const result = await interceptCreateForModal({
      toolName: "create_week_item",
      args: { title: "Disabled" },
      context: baseContext,
      convoState,
    });
    expect("error" in result).toBe(true);
    expect(mockInsertProposal).not.toHaveBeenCalled();
    // Flag stays clean.
    expect(convoState.modalAlreadyOpened).toBe(false);
  });
});

describe("stopOnModalOpened predicate", () => {
  it("returns true when latest step has any modalOpened toolResult", () => {
    const steps = [
      {
        toolResults: [
          { toolName: "create_week_item", output: { modalOpened: true, proposalId: "prop_1" } },
        ],
      },
    ];
    expect(stopOnModalOpened({ steps } as never)).toBe(true);
  });

  it("returns false when latest step has no modalOpened toolResults", () => {
    const steps = [
      { toolResults: [{ toolName: "get_clients", output: [{ name: "Convergix" }] }] },
    ];
    expect(stopOnModalOpened({ steps } as never)).toBe(false);
  });

  it("returns false when steps is empty", () => {
    expect(stopOnModalOpened({ steps: [] } as never)).toBe(false);
  });

  it("returns false when latest step has no toolResults at all", () => {
    expect(stopOnModalOpened({ steps: [{}] } as never)).toBe(false);
  });

  it("returns true when ANY of multiple parallel toolResults has modalOpened", () => {
    const steps = [
      {
        toolResults: [
          { toolName: "get_clients", output: [{ name: "Convergix" }] },
          { toolName: "create_week_item", output: { modalOpened: true, proposalId: "prop_2" } },
        ],
      },
    ];
    expect(stopOnModalOpened({ steps } as never)).toBe(true);
  });
});

describe("extractInterceptedProposals", () => {
  it("returns [] when no toolResults", () => {
    expect(extractInterceptedProposals({ steps: [{}] })).toEqual([]);
  });

  it("returns [] when toolResults exist but none have modalOpened", () => {
    const result = {
      steps: [
        { toolResults: [{ toolName: "get_clients", output: [] }] },
      ],
    };
    expect(extractInterceptedProposals(result)).toEqual([]);
  });

  it("extracts a single intercepted proposal from step 0", () => {
    const result = {
      steps: [
        {
          toolResults: [
            {
              toolName: "create_week_item",
              output: {
                modalOpened: true,
                proposalId: "prop_1",
                kind: "task" as const,
                title: "Concept Writeup",
              },
            },
          ],
        },
      ],
    };
    const out = extractInterceptedProposals(result);
    expect(out).toHaveLength(1);
    expect(out[0].proposalId).toBe("prop_1");
    expect(out[0].kind).toBe("task");
  });

  it("extracts multiple intercepted proposals (multi-detect) and ignores non-intercept results", () => {
    const result = {
      steps: [
        {
          toolResults: [
            { toolName: "get_clients", output: [{ name: "AG1" }] },
            {
              toolName: "create_project",
              output: {
                modalOpened: true,
                proposalId: "prop_proj",
                kind: "retainer" as const,
                title: "AG1 Pro 2026",
              },
            },
            {
              toolName: "create_week_item",
              output: {
                modalOpened: true,
                proposalId: "prop_task_1",
                kind: "task" as const,
                title: "Concept Writeup",
                parentProjectName: "AG1 Pro 2026",
              },
            },
          ],
        },
      ],
    };
    const out = extractInterceptedProposals(result);
    expect(out).toHaveLength(2);
    expect(out.map((r) => r.proposalId)).toEqual(["prop_proj", "prop_task_1"]);
  });

  it("ignores tool error outputs (output without modalOpened)", () => {
    const result = {
      steps: [
        {
          toolResults: [
            {
              toolName: "create_week_item",
              output: { error: "A form is already open." },
            },
          ],
        },
      ],
    };
    expect(extractInterceptedProposals(result)).toEqual([]);
  });
});

describe("composeButtonBearingReply", () => {
  const single: InterceptResult = {
    modalOpened: true,
    proposalId: "prop_1",
    kind: "task",
    title: "Concept Writeup",
  };

  const proj: InterceptResult = {
    modalOpened: true,
    proposalId: "prop_proj",
    kind: "retainer",
    title: "AG1 Pro 2026",
  };

  const task1: InterceptResult = {
    modalOpened: true,
    proposalId: "prop_task_1",
    kind: "task",
    title: "Concept Writeup (May 4)",
    parentProjectName: "AG1 Pro 2026",
  };

  const task2: InterceptResult = {
    modalOpened: true,
    proposalId: "prop_task_2",
    kind: "task",
    title: "Concept Writeup (May 11)",
    parentProjectName: "AG1 Pro 2026",
  };

  it("single intercept: text uses BOT_SINGLE_INTERCEPT_REPLY + 1 actions block with 1 button", () => {
    const out = composeButtonBearingReply([single], "");
    expect(out.text).toMatch(/Click the button below/);
    const actionsBlocks = out.blocks.filter((b) => b.type === "actions");
    expect(actionsBlocks).toHaveLength(1);
    const buttons = actionsBlocks[0].elements ?? [];
    expect(buttons).toHaveLength(1);
    expect(buttons[0].action_id).toBe("open_create_modal");
    expect(buttons[0].value).toBe("prop_1");
  });

  it("multi intercept: text counts items + 1 button per intercepted proposal (project first)", () => {
    const out = composeButtonBearingReply([proj, task1, task2], "");
    expect(out.text).toMatch(/I caught 3 items/);
    const buttons =
      (out.blocks.find((b) => b.type === "actions")?.elements as Array<{
        action_id?: string;
        value?: string;
      }>) ?? [];
    expect(buttons).toHaveLength(3);
    // Project first (kind === "project" or "retainer" sorts ahead of "task").
    expect(buttons[0].value).toBe("prop_proj");
    expect(buttons[1].value).toBe("prop_task_1");
    expect(buttons[2].value).toBe("prop_task_2");
  });

  it("multi intercept: task buttons are disabled (style=danger) when parentProjectName is set and project is also staged", () => {
    const out = composeButtonBearingReply([proj, task1, task2], "");
    const buttons = (out.blocks.find((b) => b.type === "actions")?.elements as Array<{
      action_id?: string;
      style?: string;
    }>) ?? [];
    // Project button is primary / enabled.
    expect(buttons[0].style).toBe("primary");
    // Tasks point to a not-yet-saved project — surfaced as danger style and the
    // "task_button_disabled" action_id, the Wave 8 handler will ephemeral-respond.
    expect(buttons[1].action_id).toBe("task_button_disabled");
    expect(buttons[2].action_id).toBe("task_button_disabled");
  });

  it("multi intercept WITHOUT a project: tasks are enabled (open_create_modal)", () => {
    const standaloneTask: InterceptResult = {
      modalOpened: true,
      proposalId: "prop_solo",
      kind: "task",
      title: "Standalone task",
    };
    const out = composeButtonBearingReply([single, standaloneTask], "");
    const buttons = (out.blocks.find((b) => b.type === "actions")?.elements as Array<{
      action_id?: string;
    }>) ?? [];
    // Both tasks; no project staged in this batch -> both buttons open the create modal.
    expect(buttons.every((b) => b.action_id === "open_create_modal")).toBe(true);
  });

  it("mixed read+create reply: prepends LLM text as a section block above buttons", () => {
    const out = composeButtonBearingReply(
      [single],
      "Convergix has 3 retainers active.",
    );
    // Order: text-from-LLM section, then bot-intro section (BOT_SINGLE_INTERCEPT_REPLY), then actions.
    const sections = out.blocks.filter((b) => b.type === "section");
    expect(sections.length).toBeGreaterThanOrEqual(2);
    const firstText = (sections[0].text as { text?: string })?.text ?? "";
    expect(firstText).toContain("Convergix has 3 retainers active");
    // Top-level `text` field carries the same combined string for accessibility / fallbacks.
    expect(out.text).toContain("Convergix has 3 retainers active");
    expect(out.text).toContain("Click the button below");
  });

  it("single intercept with empty replyText: no extra section block, just intro + button", () => {
    const out = composeButtonBearingReply([single], "");
    const sections = out.blocks.filter((b) => b.type === "section");
    expect(sections).toHaveLength(1);
  });
});

/**
 * Wave 7 / Builder 7 — bot LLM intercept helper.
 *
 * Per Spike C resolution + pre-plan v7 §"Bot LLM intercept hook (Pattern A)":
 * the bot's `generateText` loop calls `interceptCreateForModal()` from each
 * modal-routed `create_*` tool's `execute()` callback. The helper:
 *
 *   1. Step-aware flag check on `convoState`. Allow N parallel calls in the
 *      SAME step (multi-detect). Reject calls in any subsequent step.
 *   2. Insert proposal row via the shared `insertProposal()` helper. Carries
 *      `intent_group_id`, optional `pendingProjectName`, optional
 *      `parentProposalId` (set later by the caller for child task chaining).
 *   3. Set `convoState.modalAlreadyOpened = true` and record the step index.
 *   4. Return `{ modalOpened, proposalId, kind, title, parentProjectName? }`
 *      to the LLM. **Does NOT call `views.open`** — Slack does not provide a
 *      `trigger_id` on message events. The bot wrapper composes a Block Kit
 *      button-bearing reply; user clicks the button and the resulting
 *      block_actions payload to /api/slack/interactivity carries a fresh
 *      `trigger_id` to open the modal.
 *
 * Termination is the joint responsibility of:
 *   - `stopOnModalOpened` custom `stopWhen` predicate (Strategy 1) — wired in
 *     bot.ts alongside `stepCountIs(MAX_STEPS)`.
 *   - the step-aware flag (Strategy 2) — defends against parallel-step LLM
 *     misbehavior even if Strategy 1 fails to fire.
 *   - system prompt belt (Strategy 3, defensive) — bot-context-behaviors.ts.
 *
 * `composeButtonBearingReply()` is the post-loop helper used by bot.ts to
 * build the chat.postMessage body when one or more proposals were
 * intercepted. Single-button case uses BOT_SINGLE_INTERCEPT_REPLY; multi-detect
 * uses formatBotMultiDetectReply(N) and renders one Block Kit button per
 * proposal (project first, tasks after with a disabled state when their
 * parent project is staged but not yet saved).
 */

import type { StopCondition } from "ai";
import { isModalInterceptEnabled } from "@/lib/feature-flags";
import { insertProposal } from "./proposal";
import { BOT_SINGLE_INTERCEPT_REPLY, formatBotMultiDetectReply } from "./copy";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type InterceptToolName =
  | "create_project"
  | "create_week_item"
  | "create_team_member";

export type InterceptKind = "project" | "task" | "team_member" | "retainer";

/**
 * Per-conversation state threaded through `createBotTools`. The bot wrapper
 * resets this once per `handleDirectMessage` invocation. `currentStep` is
 * updated by the `prepareStep` callback wired into `generateText` so the
 * intercept can record the step index where the modal opened.
 */
export interface ConvoState {
  modalAlreadyOpened: boolean;
  openStep: number | null;
  /**
   * Most recent step number observed from `prepareStep`. Used by the
   * step-aware flag check to allow parallel calls in the same step but
   * reject any call in a subsequent step.
   */
  currentStep: number;
}

export interface InterceptContext {
  slackUserId: string;
  channelId: string;
  threadTs: string | null;
  /**
   * One id per user message. Bot wrapper generates this once per
   * `handleDirectMessage` call and threads it through. Multi-detect
   * proposals share it; the multi-detect chat.update on parent submit reads
   * by intent_group_id to find sibling task proposals.
   */
  intentGroupId: string;
}

export interface InterceptResult {
  modalOpened: true;
  proposalId: string;
  kind: InterceptKind;
  title: string;
  /** Set when the proposal was staged with a `pendingProjectName` hint
   *  (multi-detect child task whose parent project hasn't been saved yet). */
  parentProjectName?: string;
}

export interface InterceptError {
  error: string;
}

export interface InterceptParams {
  toolName: InterceptToolName;
  args: Record<string, unknown>;
  context: InterceptContext;
  convoState: ConvoState;
}

// ---------------------------------------------------------------------------
// interceptCreateForModal
// ---------------------------------------------------------------------------

/**
 * Stage a `bot_modal_proposals` row and return the modalOpened signal.
 * Step-aware against `convoState`. Defensive against the feature flag being
 * off (bot-tools wrapper checks the flag too; this is belt-and-suspenders).
 */
export async function interceptCreateForModal(
  params: InterceptParams,
): Promise<InterceptResult | InterceptError> {
  if (!isModalInterceptEnabled()) {
    // The bot-tools wrapper should already have routed to the legacy direct
    // write path before reaching us. If it didn't, fail loud rather than
    // silently dropping the intercept.
    return { error: "Modal intercept is disabled (MODAL_INTERCEPT_ENABLED != true)." };
  }

  const { convoState, context } = params;

  // Step-aware flag: same step -> allow (parallel multi-detect tool calls
  // in step 0 all execute before stopWhen fires). Different step -> reject.
  if (
    convoState.modalAlreadyOpened &&
    convoState.openStep !== null &&
    convoState.openStep !== convoState.currentStep
  ) {
    return {
      error:
        "A form is already open. Have the user submit or cancel it first.",
    };
  }

  const kind = mapToolToKind(params.toolName, params.args);
  const title = extractTitle(params.toolName, params.args);
  const parentProjectName =
    typeof params.args.pendingProjectName === "string"
      ? params.args.pendingProjectName
      : undefined;

  const { proposalId } = await insertProposal({
    kind: "create",
    toolName: params.toolName,
    args: params.args,
    userSlackId: context.slackUserId,
    channelId: context.channelId,
    threadTs: context.threadTs ?? null,
    intentGroupId: context.intentGroupId,
    pendingProjectName: parentProjectName,
  });

  // Mark the convo state. Parallel calls in the same step all set the same
  // openStep; the predicate above lets them through.
  if (!convoState.modalAlreadyOpened) {
    convoState.modalAlreadyOpened = true;
    convoState.openStep = convoState.currentStep;
  }

  const result: InterceptResult = {
    modalOpened: true,
    proposalId,
    kind,
    title,
  };
  if (parentProjectName) {
    result.parentProjectName = parentProjectName;
  }
  return result;
}

// ---------------------------------------------------------------------------
// stopOnModalOpened — custom `stopWhen` predicate
// ---------------------------------------------------------------------------

/**
 * Returns `true` when any toolResult in the latest step has
 * `output.modalOpened === true`. Pairs with `stepCountIs(MAX_STEPS)` in
 * bot.ts as `stopWhen: [stepCountIs(MAX_STEPS), stopOnModalOpened]`.
 *
 * Per Spike C, this saves one Anthropic API roundtrip (~1-2s p50,
 * ~2.5s p95) by terminating the loop before the LLM is re-invoked with the
 * tool result. `result.text` will be `""` when this fires; the bot wrapper
 * composes the user-facing reply itself via `composeButtonBearingReply`.
 */
export const stopOnModalOpened: StopCondition<Record<string, never>> = ({
  steps,
}) => {
  const last = steps.at(-1);
  const results = last?.toolResults ?? [];
  return results.some(
    (r) =>
      (r as { output?: { modalOpened?: boolean } }).output?.modalOpened === true,
  );
};

// ---------------------------------------------------------------------------
// extractInterceptedProposals
// ---------------------------------------------------------------------------

interface StepLike {
  toolResults?: Array<{
    toolName?: string;
    output?: unknown;
  }>;
}

/**
 * Walk the result of `generateText` and collect every InterceptResult that
 * came back from a modal-routed tool. Per Spike C, AI SDK v6 places parallel
 * tool calls in the same step, and `stopOnModalOpened` halts the loop after
 * the first step with a modalOpened result, so the proposals always land in
 * step 0. We still iterate every step to be robust against future SDK
 * behavior changes.
 */
export function extractInterceptedProposals(result: {
  steps: StepLike[];
}): InterceptResult[] {
  const out: InterceptResult[] = [];
  for (const step of result.steps) {
    if (!step.toolResults) continue;
    for (const r of step.toolResults) {
      const output = r.output as Partial<InterceptResult> | undefined;
      if (output && output.modalOpened === true && typeof output.proposalId === "string") {
        out.push({
          modalOpened: true,
          proposalId: output.proposalId,
          kind: output.kind as InterceptKind,
          title: output.title ?? "(untitled)",
          ...(output.parentProjectName ? { parentProjectName: output.parentProjectName } : {}),
        });
      }
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// composeButtonBearingReply
// ---------------------------------------------------------------------------

interface ButtonElement {
  type: "button";
  text: { type: "plain_text"; text: string; emoji: true };
  action_id: string;
  value: string;
  style?: "primary" | "danger";
}

interface SectionBlock {
  type: "section";
  text: { type: "mrkdwn"; text: string };
}

interface ActionsBlock {
  type: "actions";
  elements: ButtonElement[];
}

export type ReplyBlock = SectionBlock | ActionsBlock;

export interface BotReply {
  text: string;
  blocks: ReplyBlock[];
}

/**
 * Build a `chat.postMessage` payload for one or more intercepted proposals.
 *
 * - Single intercept: top-level text = BOT_SINGLE_INTERCEPT_REPLY; one
 *   button labelled by kind + title with action_id="open_create_modal".
 * - Multi intercept: top-level text = formatBotMultiDetectReply(N); one
 *   button per proposal. Project / retainer proposals sort before tasks.
 *   When a project is staged in the same batch and a task carries a
 *   `parentProjectName`, the task button surfaces in `danger` style with
 *   `action_id="task_button_disabled"` — Wave 8's interactivity handler
 *   responds with the TASK_BUTTON_DISABLED ephemeral. Once the project
 *   submits, Wave 8's chat.update flow re-emits the buttons with
 *   `action_id="open_create_modal"` and the resolved projectId in `value`.
 * - Mixed read+create: when the LLM also produced text alongside intercepts
 *   (single-step parallel: read tool result + create_* result), `replyText`
 *   is non-empty. We prepend it as a section block so the user sees both
 *   the answer and the form button in ONE message (no double-post).
 */
export function composeButtonBearingReply(
  intercepted: InterceptResult[],
  replyText: string,
): BotReply {
  const blocks: ReplyBlock[] = [];

  // 1. LLM text (mixed read+create) prepended.
  if (replyText.trim().length > 0) {
    blocks.push({
      type: "section",
      text: { type: "mrkdwn", text: replyText },
    });
  }

  // 2. Bot intro (single vs multi).
  const introText =
    intercepted.length === 1
      ? BOT_SINGLE_INTERCEPT_REPLY
      : formatBotMultiDetectReply(intercepted.length);
  blocks.push({
    type: "section",
    text: { type: "mrkdwn", text: introText },
  });

  // 3. One button per intercepted proposal.
  // Sort: project / retainer first, tasks after. Stable within each group.
  const sorted = [...intercepted].sort((a, b) => kindRank(a.kind) - kindRank(b.kind));

  // Determine: does this batch have a project / retainer? If yes, every task
  // whose `parentProjectName` is set surfaces as disabled.
  const projectInBatch = intercepted.some(
    (r) => r.kind === "project" || r.kind === "retainer",
  );

  const buttons: ButtonElement[] = sorted.map((r) => buildButton(r, projectInBatch));
  blocks.push({ type: "actions", elements: buttons });

  // Top-level `text` field: combined for accessibility / push-notification
  // fallback. Slack uses it when blocks render fails.
  const fallback = replyText.trim().length > 0 ? `${replyText}\n\n${introText}` : introText;

  return { text: fallback, blocks };
}

function buildButton(
  r: InterceptResult,
  projectInBatch: boolean,
): ButtonElement {
  const isTaskWithStagedParent =
    r.kind === "task" && projectInBatch && !!r.parentProjectName;

  const label = formatButtonLabel(r.kind, r.title);
  const actionId = isTaskWithStagedParent ? "task_button_disabled" : "open_create_modal";
  const button: ButtonElement = {
    type: "button",
    text: { type: "plain_text", text: label, emoji: true },
    action_id: actionId,
    value: r.proposalId,
  };
  if (r.kind === "project" || r.kind === "retainer") {
    button.style = "primary";
  } else if (isTaskWithStagedParent) {
    button.style = "danger";
  }
  return button;
}

const KIND_LABEL: Record<InterceptKind, string> = {
  project: "Project",
  retainer: "Retainer",
  task: "Task",
  team_member: "Team Member",
};

// Slack button text is hard-capped at 75 chars; truncate the title side
// while preserving the kind prefix.
const BUTTON_TEXT_LIMIT = 70;

function formatButtonLabel(kind: InterceptKind, title: string): string {
  const prefix = `${KIND_LABEL[kind]}: `;
  const room = BUTTON_TEXT_LIMIT - prefix.length;
  if (title.length <= room) return `${prefix}${title}`;
  return `${prefix}${title.slice(0, room - 1)}…`;
}

function kindRank(kind: InterceptKind): number {
  if (kind === "project" || kind === "retainer") return 0;
  if (kind === "team_member") return 1;
  return 2; // task
}

// ---------------------------------------------------------------------------
// Internal mappers
// ---------------------------------------------------------------------------

function mapToolToKind(
  toolName: InterceptToolName,
  args: Record<string, unknown>,
): InterceptKind {
  if (toolName === "create_project") {
    return args.isRetainer === true || args.engagementType === "retainer"
      ? "retainer"
      : "project";
  }
  if (toolName === "create_week_item") return "task";
  if (toolName === "create_team_member") return "team_member";
  // Unreachable: TypeScript narrows the union, but defensive default.
  throw new Error(`Unknown intercept tool: ${toolName as string}`);
}

function extractTitle(
  toolName: InterceptToolName,
  args: Record<string, unknown>,
): string {
  if (toolName === "create_project") {
    return typeof args.name === "string" && args.name.length > 0
      ? args.name
      : "(untitled)";
  }
  if (toolName === "create_week_item") {
    return typeof args.title === "string" && args.title.length > 0
      ? args.title
      : "(untitled)";
  }
  if (toolName === "create_team_member") {
    if (typeof args.fullName === "string" && args.fullName.length > 0) {
      return args.fullName;
    }
    if (typeof args.name === "string" && args.name.length > 0) {
      return args.name;
    }
    return "(untitled)";
  }
  return "(untitled)";
}

